import { afterEach, describe, expect, it, vi } from "vitest";

interface SwEvent {
  data?: unknown;
  source?: { id?: string };
  request?: { mode: string; url: string };
  clientId?: string;
  resultingClientId?: string;
  waitUntil?: (p: Promise<unknown>) => void;
  respondWith?: (p: Promise<unknown>) => void;
