Let's inspect the current `service-worker.ts` and tests fully. We already have. Need edit carefully.

Design `service-worker.ts`:
Current:
```ts
export function setupServiceWorker(wid: string, base: string): void {
  if (!("serviceWorker" in navigator)) return;
  if (document.documentElement.dataset.pathlandServiceWorker == null) {
    void navigator.serviceWorker.getRegistrations().then(...).catch(...);
    return;
  }
  void navigator.serviceWorker
    .register(`${base}/sw.js`, { scope: "/" })
    .then((reg) => {
      const post = (): void => {
        const target = reg.active ?? navigator.serviceWorker.controller;
        target?.postMessage({ type: "pathland-wid", wid });
      };
      post();
      reg.addEventListener?.("updatefound", post);
      void navigator.serviceWorker.ready.then(post);
      navigator.serviceWorker.addEventListener?.("controllerchange", post);
    })
    .catch(...)
}
```

We need keepalive interval. We want to avoid starting multiple intervals if `setupServiceWorker` called once per page. It is called once. But `pageshow` persisted may call start again. Use a module-level or function-level timer variable.

Implementation:
```ts
const KEEPALIVE_MS = 20_000;
const KEEPALIVE_MESSAGE = { type: "pathland-keepalive" } as const;

export function setupServiceWorker(wid: string, base: string): void {
  if (!("serviceWorker" in navigator)) return;
  if (document.documentElement.dataset.pathlandServiceWorker == null) {
    void navigator.serviceWorker.getRegistrations()...
    return;
  }

  let keepAliveTimer: number | undefined;
  let registration: ServiceWorkerRegistration | undefined;

  const target = (): ServiceWorker | null =>
    navigator.serviceWorker.controller ?? registration?.active ?? null;

  const postWid = (): void => {
    target()?.postMessage({ type: "pathland-wid", wid });
  };

  const ping = (): void => {
    target()?.postMessage({ type: "pathland-keepalive" });
  };

  const startKeepAlive = (): void => {
    if (keepAliveTimer !== undefined) return;
    keepAliveTimer = window.setInterval(ping, KEEPALIVE_MS);
  };

  const stopKeepAlive = (): void => {
    if (keepAliveTimer === undefined) return;
    window.clearInterval(keepAliveTimer);
    keepAliveTimer = undefined;
  };

  void navigator.serviceWorker
    .register(`${base}/sw.js`, { scope: "/" })
    .then((reg) => {
      registration = reg;
      const seed = (): void => {
        postWid();
        startKeepAlive();
      };
      seed();
      reg.addEventListener?.("updatefound", seed);
      void navigator.serviceWorker.ready.then(seed);
      navigator.serviceWorker.addEventListener?.("controllerchange", seed);
    })
    .catch((err) => log.warn("sw", `service worker registration failed: ${err}`));

  window.addEventListener(
    "pagehide",
    (event) => {
      if ((event as PageTransitionEvent).persisted) return;
      stopKeepAlive();
      target()?.postMessage({ type: "pathland-pagehide" });
    },
    { once: true },
  );

  window.addEventListener("pageshow", (event) => {
    if (!(event as PageTransitionEvent).persisted) return;
    postWid();
    startKeepAlive();
  });

  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") ping();
  });

  window.addEventListener("focus", ping);
}
```
