const STORE = "pathland-sw";
const KEY_PREFIX = "/__pathland-wid/";
// A reload or in-site navigation creates the next window client quickly; give it
// this long before deciding that the last window really closed.
const UNREGISTER_GRACE_MS = 2000;

// Fast path for the current worker lifetime: the Cache API is the persistent
// fallback (the worker can be evicted between events).
const wids = new Map();

// The cache key must be an ABSOLUTE URL: Safari has thrown on a relative URL in the
// worker's Request constructor (and the throw used to be swallowed silently).
function widKey(clientId) {
  return new Request(new URL(KEY_PREFIX + clientId, self.location.origin).href);
}

async function remember(clientId, wid) {
  if (!clientId || !wid) return;
  wids.set(clientId, wid);
  try {
    const cache = await caches.open(STORE);
    await cache.put(widKey(clientId), new Response(wid));
  } catch (err) {
    // Best effort — but visible: a silent failure here means the SSR renders defaults.
    console.warn("[pathland] failed to remember the window id", err);
  }
}

async function recall(clientId) {
  if (!clientId) return null;
  const remembered = wids.get(clientId);
  if (remembered !== undefined) return remembered;
  try {
    const cache = await caches.open(STORE);
    const hit = await cache.match(widKey(clientId));
    return hit ? await hit.text() : null;
  } catch (err) {
    console.warn("[pathland] failed to recall the window id", err);
    return null;
  }
}

// Unregister when the last window closes, so the next browser session's first
// navigation is uncontrolled and does not wait for a cold worker to boot. The
// grace period lets a reload/in-site navigation create its next client first.
async function unregisterIfLastClient(senderId) {
  await new Promise((resolve) => setTimeout(resolve, UNREGISTER_GRACE_MS));
  let windows;
  try {
    windows = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
  } catch (err) {
    console.warn("[pathland] failed to list windows; keeping the worker", err);
    return;
  }
  const others = windows.filter((client) => client.id !== senderId);
  if (others.length > 0) return;
  wids.clear();
  try {
    await caches.delete(STORE);
  } catch (err) {
    console.warn("[pathland] failed to clear the window-id store", err);
  }
  await self.registration.unregister();
}

