                ServerFixtures.text("local"),
                ServerFixtures.proxy("http://b.example"));
        PathlandSession session = new PathlandSession(
                "s1", new InMemoryStateStore(), app, EnvironmentData.of("/"),
                false, "/_pathland", "scope", PathlandTelemetry.NOOP, "/");
